    superPowersTitle: 'सुपरपावर',
    superPowersDesc: 'सुपरपावर्स एक स्टिकर बैज ल आप खर्च कर सकत हंवय तक पहुंच म बदल देत हंवय । हर दो सप्ताह म आपके बैज अनुदान बढ़त हवय, अउ घर के फीड के शीर्ष म स्लॉट म एक जगह खर्च करत हवय । टीम अप हर हर एक बर खुला हवय अउ आठ तक के खाता के पोर्टफोलियो शक्ति ल जोड़त हवय, अउ प्रत्येक सदस्य ल अपन कुल खुलासा के बैज देत हवय । स्लॉट घूमथे: जब कईठन बूस्ट चलत हवय, तो दर्शकमन ल एक बैज लेवल ले इलाज करे जात हवय, ताकि उच्च स्तर अधिक बार दिखाए जात हवय अउ जम्मो मनखे अभी घलो खिड़की ल प्राप्त करत हवयं जेहर ओमनके प्रदान करे जात हवय ।',
